import{_ as s}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as l,D as c,o as r,c as p,I as u,w as d,k as t,a as m,R as h,b as _,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const Y=JSON.parse('{"title":"目录与模块","description":"","frontmatter":{"title":"目录与模块","author":"阿源","date":"2026/09/20 10:00","categories":["开源项目"],"tags":["RuoYi","开源项目"],"showArticleMetadata":false},"headers":[],"relativePath":"open-source/01-RuoYi/02-目录与模块.md","filePath":"open-source/01-RuoYi/02-目录与模块.md","lastUpdated":1789912873000}'),y={name:"open-source/01-RuoYi/02-目录与模块.md"},b=t("h1",{id:"目录与模块",tabindex:"-1"},[m("目录与模块 "),t("a",{class:"header-anchor",href:"#目录与模块","aria-label":'Permalink to "目录与模块"'},"​")],-1),k=h(`<h2 id="本篇目标" tabindex="-1">本篇目标 <a class="header-anchor" href="#本篇目标" aria-label="Permalink to &quot;本篇目标&quot;">​</a></h2><p>用根 POM 和各模块的源码目录还原后端的职责边界，并分清“模块依赖”和“请求调用”是两种不同关系。读完后，可以判断一个新功能更可能落在哪个模块，以及下一步应该打开哪些文件。</p><h2 id="源码入口" tabindex="-1">源码入口 <a class="header-anchor" href="#源码入口" aria-label="Permalink to &quot;源码入口&quot;">​</a></h2><ul><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/pom.xml" target="_blank" rel="noreferrer">根目录 Maven POM</a>：模块清单与统一依赖版本。</li><li><a href="https://gitee.com/y_project/RuoYi-Vue/tree/master/ruoyi-admin" target="_blank" rel="noreferrer">ruoyi-admin 目录</a>：Spring Boot 应用、Web 控制器和运行配置。</li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-framework/pom.xml" target="_blank" rel="noreferrer">ruoyi-framework POM</a>：框架层依赖及基础设施。</li><li><a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">RuoYi-Vue 仓库</a>：从当前分支确认实际目录。</li></ul><h2 id="调用链或模块关系" tabindex="-1">调用链或模块关系 <a class="header-anchor" href="#调用链或模块关系" aria-label="Permalink to &quot;调用链或模块关系&quot;">​</a></h2><p>先从根 POM 的 <code>&lt;modules&gt;</code> 读取模块，再打开每个模块的 POM 核对依赖。主干关系可概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>ruoyi-admin（Web 应用入口）</span></span>
<span class="line"><span>├── ruoyi-framework（Web、安全与基础设施）</span></span>
<span class="line"><span>│   └── ruoyi-system（系统业务）</span></span>
<span class="line"><span>│       └── ruoyi-common（公共代码）</span></span>
<span class="line"><span>├── ruoyi-quartz（定时任务）</span></span>
<span class="line"><span>│   └── ruoyi-common（公共代码）</span></span>
<span class="line"><span>└── ruoyi-generator（代码生成）</span></span>
<span class="line"><span>    └── ruoyi-common（公共代码）</span></span></code></pre></div><p>这张图只表达代码组织和主要依赖方向，不表示每个 HTTP 请求都经过所有模块。常见源码目录是 <code>ruoyi-admin/.../web/controller</code>、<code>ruoyi-framework/.../framework</code>、<code>ruoyi-system/.../system</code> 与 <code>ruoyi-common/.../common</code>；<code>ruoyi-quartz</code> 和 <code>ruoyi-generator</code> 则按各自功能组织任务、模板及数据访问代码。</p><h2 id="核心实现" tabindex="-1">核心实现 <a class="header-anchor" href="#核心实现" aria-label="Permalink to &quot;核心实现&quot;">​</a></h2><p>Maven 聚合 POM 负责声明模块并统一版本；<code>ruoyi-admin</code> 负责把框架、业务与可选功能装配成可运行的 Web 应用。<code>ruoyi-system</code> 常见的业务切片是 domain、mapper、service：数据对象描述业务结构，Mapper 对接持久层，Service 承担业务操作。框架配置和公共注解、工具类会被多个业务切片复用。</p><p>阅读一个功能时，可以先由 URL 和 Controller 定位入口，再沿依赖注入追到 Service、Mapper 及 SQL；只有遇到鉴权、事务、数据范围或异常转换时，再回头读相关框架配置和切面。</p><h2 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h2><p>模块是编译和复用边界，不是业务流程图。理解目录的最好方式，是先从 POM 建立静态依赖图，再用一条真实请求验证哪些边界确实参与运行。</p><h2 id="可验证实验" tabindex="-1">可验证实验 <a class="header-anchor" href="#可验证实验" aria-label="Permalink to &quot;可验证实验&quot;">​</a></h2><ol><li>在根 POM 中逐项勾出模块，并在各模块 POM 中记录 <code>ruoyi-*</code> 依赖。</li><li>对照 <code>ruoyi-system</code> 的一个功能，分别找到其 Controller、Service 接口与实现、Mapper，以及 XML SQL（若该功能使用 XML）。</li><li>在 IDE 的依赖视图中检查 <code>ruoyi-admin</code> 的传递依赖，比较它与根 POM 聚合模块列表的区别。</li></ol><p>以上目录与调用路径以当前阅读版本为参照；不同 RuoYi 版本、分支或二次开发仓库的具体路径和实现可能不同，请以本地 checkout 为准。</p><h2 id="关联笔记与源码链接" tabindex="-1">关联笔记与源码链接 <a class="header-anchor" href="#关联笔记与源码链接" aria-label="Permalink to &quot;关联笔记与源码链接&quot;">​</a></h2><ul><li><a href="/open-source/01-RuoYi/01-项目概览">项目概览</a></li><li>下一篇：<a href="/open-source/01-RuoYi/03-启动链路">启动链路</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/pom.xml" target="_blank" rel="noreferrer">根目录 Maven POM</a> · <a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-framework/pom.xml" target="_blank" rel="noreferrer">ruoyi-framework POM</a></li></ul>`,18);function g(e,P,M,R,q,x){const i=s,n=c("ClientOnly");return r(),p("div",null,[b,u(n,null,{default:d(()=>{var a,o;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((o=e.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(r(),_(i,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),k])}const w=l(y,[["render",g]]);export{Y as __pageData,w as default};
